	/** 
	 * jumpstart the process by instantiating2 Notebook
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		notebookId = NotebookService.getNotebookInstance()
		.createNotebook( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		NotebookService.getNotebookInstance()
				.createNotebook( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.notebookSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Notebook : " + successValue.getNotebookId());
							  if (successValue.getNotebookId().equals(notebookId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfNotebookList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Notebook test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on notebook consumed")
					);
			subscriber.notebookSubscribe( notebookId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Notebook : " + successValue.getNotebookId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfNotebookList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on notebook for notebookId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Notebook. 
	 */
	protected Notebook read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Notebook" );

		Notebook entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Notebook with primary key" );
		msg.append( notebookId );
		
		NotebookFetchOneSummary fetchOneSummary = new NotebookFetchOneSummary( notebookId );

		try {
			entity = NotebookService.getNotebookInstance().getNotebook( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Notebook " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Notebook.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Notebook." );

		StringBuilder msg = new StringBuilder( "Failed to update a Notebook : " );        
		Notebook entity = read();
		UpdateNotebookCommand command = generateUpdateCommand();
		command.setNotebookId(entity.getNotebookId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Notebook." );

			// for use later on...
			notebookId = entity.getNotebookId();

			NotebookService proxy = NotebookService.getNotebookInstance();  

			proxy.updateNotebook( command ).get();

			LOGGER.info( "-- Successfully saved Notebook - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + notebookId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Notebook.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Notebook." );

		Notebook entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Notebook with id " + notebookId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Notebook with id " + notebookId );

			throw e;
		}

		try{
			NotebookService.getNotebookInstance().delete( new DeleteNotebookCommand( entity.getNotebookId() ) ).get();
			LOGGER.info( "-- Successfully deleted Notebook with id " + notebookId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Notebook with id " + notebookId );

			throw e;
		}
	}

	/**
	 * get all Notebooks.
	 */
	protected List<Notebook> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Notebooks:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Notebook : " );        
		List<Notebook> collection  = new ArrayList<>();

		try {
			// call the static get method on the NotebookService
			collection = NotebookService.getNotebookInstance().getAllNotebook();
			assertNotNull( collection, "An Empty collection of Notebook was incorrectly returned.");
			
			// Now print out the values
			Notebook entity = null;            
			Iterator<Notebook> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getNotebookId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

