	protected UpdateNotebookCommand generateUpdateCommand() {
	        UpdateNotebookCommand command = new UpdateNotebookCommand( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new RepositoryRef(),  null,  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  NotebookLanguage.values()[0] );
			
			return( command );
		}
